 81	// ApproveConversion implements the project-owned sales_lead.approve_conversion Handler.
 82	func ApproveConversion(ctx context.Context, caps capabilities.ApproveConversionCapabilities, input capabilities.ApproveConversionInput) (capabilities.ApproveConversionOutput, error) {
