 96		if err != nil {
 97			return capabilities.ApproveConversionOutput{}, err
 98		}
 99		if lead.Status != schema.SalesLeadStatus("qualified") || comparison < 0 || exists {
100			return capabilities.ApproveConversionOutput{}, &capabilities.BusinessError{Code: "sales_lead.approval_invalid"}
101		}
102		now := time.Now().UTC()
103		updated, err := caps.SalesLead.ConditionalUpdate(ctx, data.NewSalesLeadUpdate(lead.ID).
104			SetStatus(schema.SalesLeadStatus("converted")).
105			SetStatusChangedAt(now).
106			ClearRejectionReason().
107			RequireStatusEqual(lead.Status, "sales_lead.conversion_conflict").
108			WithExpectedUpdatedAt(lead.UpdatedAt))
109		if err != nil {
110			return capabilities.ApproveConversionOutput{}, err
111		}
