125		companyName := lead.CompanyName
126		_, err = caps.Notifications.Dispatch(ctx, capabilities.ApproveConversionNotificationIntent{
127			EventType:        "lead.conversion_approved",
128			SourceEventID:    "lead-conversion-approved:" + string(lead.ID),
129			RecipientUserIDs: []string{caps.Execution.Principal().UserID},
130			SubjectObjectKey: "sales_lead",
