132			SubjectVersion:   updated.UpdatedAt,
133			DedupeKey:        "lead-conversion-approved:" + string(lead.ID),
134			GroupKey:         "lead-conversion:" + string(lead.ID),
135			Alert:            true,
136			OccurredAt:       now,
137			Variables: []capabilities.ApproveConversionNotificationVariable{
138				{Key: "company_name", StringValue: &companyName},
139			},
140		})
141		if err != nil {
