 13	func SendOverdueReminders(ctx context.Context, caps capabilities.SendOverdueRemindersCapabilities, input capabilities.SendOverdueRemindersInput) (capabilities.SendOverdueRemindersOutput, error) {
 14		_ = input
 15		now := time.Now()
 16		location, err := time.LoadLocation("Asia/Shanghai")
 17		if err != nil {
 18			return capabilities.SendOverdueRemindersOutput{}, err
 19		}
 20		localNow := now.In(location)
 21		cutoff := localNow.AddDate(0, 0, -7)
 22		businessDate := time.Date(localNow.Year(), localNow.Month(), localNow.Day(), 0, 0, 0, 0, location)
 23		leads, err := caps.SalesLead.List(ctx, data.NewSalesLeadQuery().
 24			WhereStatusEqual(schema.SalesLeadStatus("contacted")).
 25			OrderByIDAscending().
 26			Page(1, 200))
 27		if err != nil {
 28			return capabilities.SendOverdueRemindersOutput{}, err
 29		}
 30		eligible := make([]schema.SalesLead, 0, len(leads))
 31		queries := make([]data.FollowupReminderReceiptQuery, 0, len(leads))
 32		for _, lead := range leads {
 33			if !lead.StatusChangedAt.Before(cutoff) {
 34				continue
 35			}
 36			key := "followup-overdue:" + string(lead.ID) + ":" + businessDate.Format("2006-01-02")
 37			eligible = append(eligible, lead)
