func (s *WorkflowApplicationService) runInvokedWorkflow(ctx context.Context, workflowKey string, payload map[string]any, principal principalmodel.Principal, mode invocationcontract.WorkflowEntryMode, trigger string) (workflowmodel.WorkflowRunResult, error) {
	if err := workflowAuthorizeCommand(principal); err != nil {
		return workflowmodel.WorkflowRunResult{}, err
	}
	workflow, ok := s.registry.Get(workflowKey)
	if !ok {
		return workflowmodel.WorkflowRunResult{}, notFound("backend.workflow.not_found")
	}
	if len(invocationcontract.ValidateWorkflowPermission(workflow, principal)) > 0 {
		return workflowmodel.WorkflowRunResult{}, forbidden("backend.workflow.run_permission_required")
	}
	// Cross-resource callers validate their authored input contract before
	// publication. This execution boundary receives concrete rendered values and
	// independently closes target mode and permission before running anything.
	if issues := invocationcontract.ValidateWorkflowTarget(workflow, mode); len(issues) > 0 {
		return workflowmodel.WorkflowRunResult{}, workflowInvocationError(issues[0])
	}
	execution, err := s.executeWorkflow(ctx, workflow, payload, principal, trigger)
	if err != nil {
		return workflowmodel.WorkflowRunResult{}, err
	}
	return workflowmodel.WorkflowRunResult{
		WorkflowKey: workflow.Key, Name: workflow.Name, Status: execution.Status,
		Action: workflow.Action, Payload: payload, Execution: execution,
	}, nil
}

func workflowInvocationError(issue invocationcontract.Issue) error {
	params := []string{"field", issue.Field, "expected", issue.Expected, "actual", issue.Actual, "reference", issue.Reference}
	switch issue.Code {
	case "invocation.workflow_disabled":
		return badRequest("backend.workflow.disabled")
	case "invocation.workflow_entry_mode_invalid":
		return badRequest("backend.workflow.entry_mode_invalid", params...)
	default:
		return badRequest("backend.workflow.invocation_invalid", params...)
	}
}

func WorkflowPayloadForRecord(objectKey string, record recordmodel.Record) map[string]any {
	return workflowPayloadForRecord(objectKey, record)
}

func workflowPayloadForRecordChange(objectKey string, record recordmodel.Record, before map[string]any, trigger string) map[string]any {
	payload := workflowpolicy.WorkflowCloneMap(record.Data)
	payload["object_key"] = objectKey
	payload["id"] = record.ID
	payload["record_id"] = record.ID
	payload["created_at"] = record.CreatedAt
	payload["updated_at"] = record.UpdatedAt
	payload["after"] = workflowpolicy.WorkflowCloneMap(record.Data)
	if before != nil {
		payload["before"] = workflowpolicy.WorkflowCloneMap(before)
		payload["changed_fields"] = workflowpolicy.WorkflowChangedRecordFieldKeys(before, record.Data)
	}
	if trigger != "" {
		payload["trigger_event"] = trigger
	}
	return payload
}

func WorkflowPayloadForRecordChange(objectKey string, record recordmodel.Record, before map[string]any, trigger string) map[string]any {
	return workflowPayloadForRecordChange(objectKey, record, before, trigger)
}

func (s *WorkflowApplicationService) workflowRetryPayload(ctx context.Context, workspaceID string, previous workflowmodel.WorkflowExecution, principal principalmodel.Principal) map[string]any {
	payload := workflowpolicy.WorkflowCloneMap(previous.Payload)
	objectKey := valueOrDefault(strings.TrimSpace(previous.ObjectKey), workflowpolicy.WorkflowPayloadString(payload, "object_key"))
	recordID := valueOrDefault(strings.TrimSpace(previous.RecordID), workflowpolicy.WorkflowPayloadString(payload, "record_id"))
	if objectKey == "" || recordID == "" {
		return payload
	}
	object, ok := s.schemaMap(ctx)[objectKey]
	if !ok {
		return payload
	}
	record, ok, err := s.recordReader.GetWorkflowRecord(ctx, workspaceID, object, recordID, principal)
	if err != nil || !ok {
		return payload
	}
	refreshed := workflowPayloadForRecord(objectKey, record)
	for _, key := range []string{"request_id", "initiating_user_id", "initiating_role_key", "scheduled_at"} {
		if value, ok := payload[key]; ok && !workflowpolicy.WorkflowValueIsEmpty(value) {
			refreshed[key] = value
		}
	}
	refreshed["retry_source_execution_id"] = previous.ID
	refreshed["retry_source_status"] = previous.Status
	if previous.LastError != "" {
		refreshed["retry_source_last_error"] = previous.LastError
	}
	return refreshed
}

