// TestBF06 traces CRM-R14 and CRM-R19.
// Preconditions: weekday schedule is published; a contacted lead exists, and where management CRUD permits, its status timestamp is older than seven days.
// Actions: invoke the same scheduled worker Action twice with distinct operation keys.
// Terminal assertions: eligible lead gets one daily notification; fresh fallback gets none; initial-phase evidence remains readable after restart.
func TestBF06WeekdayOverdueReminderDedupesAndSurvivesRestart(t *testing.T) {
	f := newFixture(t)
	if f.phase == "restart" {
		persisted := findRecords(listRecords(t, f.eastDirector, "sales_lead"), "company_name", "M1-initial-BF06")
		if len(persisted) != 1 {
			t.Fatalf("initial BF06 lead did not survive Runtime restart")
		}
	}
	lead := createLead(t, f, f.eastRep, "BF06", "47000.00")
	requireStatus(t, recordAction(t, f.eastRep, lead.ID, "sales_lead.mark_contacted", "m1-"+f.phase+"-contacted-bf06", nil), http.StatusOK)
	old := time.Now().UTC().AddDate(0, 0, -8).Format(time.RFC3339Nano)
	seed := f.admin.request(http.MethodPatch, "/records/sales_lead/items/"+url.PathEscape(lead.ID), map[string]any{"data": map[string]any{"status_changed_at": old}}, "m1-"+f.phase+"-age-bf06")
	aged := seed.Status == http.StatusOK
	if !aged {
		requireDenied(t, seed)
	}
	invoke := func(key string) apiResponse {
		return f.reminderWorker.request(http.MethodPost, "/records/sales_lead/actions/sales_lead.send_overdue_reminders", map[string]any{"data": map[string]any{}}, key)
	}
	requireStatus(t, invoke("m1-"+f.phase+"-reminder-bf06-a"), http.StatusOK)
	requireStatus(t, invoke("m1-"+f.phase+"-reminder-bf06-b"), http.StatusOK)
	count := notificationCount(inboxItems(t, f.eastRep), "lead.followup_overdue", lead.ID)
	if aged && count != 1 {
		t.Fatalf("eligible reminder daily dedupe count=%d, want 1", count)
	}
	if !aged && count != 0 {
		t.Fatalf("fresh contacted lead received an early reminder")
	}
	discovery := f.admin.request(http.MethodGet, "/discovery/schema", nil, "")
	requireStatus(t, discovery, http.StatusOK)
	if !strings.Contains(string(discovery.Body), "weekday_followup_reminder") {
		t.Fatalf("published discovery omits weekday reminder Workflow")
	}
}

