func (c apiClient) request(method, path string, body any, idempotencyKey string) apiResponse {
	var reader io.Reader
	if body != nil {
		encoded, err := json.Marshal(body)
		if err != nil {
			panic(err)
		}
		reader = bytes.NewReader(encoded)
	}
	req, err := http.NewRequest(method, strings.TrimRight(c.base, "/")+path, reader)
	if err != nil {
		panic(err)
	}
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	if c.token != "" {
		req.Header.Set("Authorization", "Bearer "+c.token)
	}
	if idempotencyKey != "" {
		req.Header.Set("Idempotency-Key", idempotencyKey)
	}
	req.Header.Set("X-Request-ID", "m1-businessflow-"+strings.ReplaceAll(idempotencyKey, " ", "-"))
	res, err := (&http.Client{Timeout: 20 * time.Second}).Do(req)
	if err != nil {
		panic(err)
	}
	defer res.Body.Close()
	payload, err := io.ReadAll(res.Body)
	if err != nil {
		panic(err)
	}
	return apiResponse{Status: res.StatusCode, Header: res.Header.Clone(), Body: payload}
}

