type record struct {
	ID        string         `json:"id"`
	Data      map[string]any `json:"data"`
	CreatedAt string         `json:"created_at"`
	UpdatedAt string         `json:"updated_at"`
}

type recordPage struct {
	Items    []record `json:"items"`
	Page     int      `json:"page"`
	PageSize int      `json:"page_size"`
	Total    int      `json:"total"`
	HasNext  bool     `json:"has_next"`
}

func listRecords(t *testing.T, client apiClient, objectKey string) []record {
	t.Helper()
	all := []record{}
	for page := 1; ; page++ {
		response := client.request(http.MethodGet, fmt.Sprintf("/records/%s?page=%d&page_size=200", url.PathEscape(objectKey), page), nil, "")
		requireStatus(t, response, http.StatusOK)
		var result recordPage
		response.decode(t, &result)
		all = append(all, result.Items...)
		if !result.HasNext {
			return all
		}
	}
}

func getRecord(t *testing.T, client apiClient, objectKey, id string) record {
	t.Helper()
	response := client.request(http.MethodGet, "/records/"+url.PathEscape(objectKey)+"/items/"+url.PathEscape(id), nil, "")
	requireStatus(t, response, http.StatusOK)
	var result record
	response.decode(t, &result)
	return result
}

func findRecords(items []record, field, expected string) []record {
	result := []record{}
	for _, item := range items {
		if fmt.Sprint(item.Data[field]) == expected {
			result = append(result, item)
		}
	}
	return result
}

func createLead(t *testing.T, f fixture, client apiClient, suffix, amount string) record {
	t.Helper()
	company := "M1-" + f.phase + "-" + suffix
	key := "m1-" + f.phase + "-create-" + strings.ToLower(suffix)
	body := map[string]any{"data": map[string]any{
		"company_name": company, "contact_name": "Acceptance Contact", "contact_phone": "+8613800000001",
		"estimated_amount": amount, "source": "website",
	}}
	response := client.request(http.MethodPost, "/records/sales_lead/actions/sales_lead.create_lead", body, key)
	requireStatus(t, response, http.StatusOK)
	var actionResult struct {
		CreatedRecords []struct {
			ObjectKey string `json:"object_key"`
			RecordID  string `json:"record_id"`
		} `json:"created_records"`
	}
	response.decode(t, &actionResult)
