// Actions: create/replay, update, advance new→contacted→qualified, and attempt a peer write.
// Terminal assertions: one durable qualified lead, updated details, audit rows, and unchanged state after denial.
func TestBF01LeadCreationLifecycleAndOwnerWriteBoundary(t *testing.T) {
	f := newFixture(t)
	lead := createLead(t, f, f.eastRep, "BF01", "88000.25")
	if fmt.Sprint(lead.Data["status"]) != "new" || fmt.Sprint(lead.Data["responsible_user_id"]) != "m1-rep-east" {
		t.Fatalf("new lead defaults/owner are incorrect: %#v", lead.Data)
	}

	replay := f.eastRep.request(http.MethodPost, "/records/sales_lead/actions/sales_lead.create_lead", map[string]any{"data": map[string]any{
		"company_name": "M1-" + f.phase + "-BF01", "contact_name": "Acceptance Contact", "contact_phone": "+8613800000001",
		"estimated_amount": "88000.25", "source": "website",
	}}, "m1-"+f.phase+"-create-bf01")
	requireStatus(t, replay, http.StatusOK)
	if count := len(findRecords(listRecords(t, f.eastRep, "sales_lead"), "company_name", "M1-"+f.phase+"-BF01")); count != 1 {
		t.Fatalf("create replay produced %d leads", count)
	}

	updated := recordAction(t, f.eastRep, lead.ID, "sales_lead.update_details", "m1-"+f.phase+"-update-bf01", map[string]any{
		"contact_name": "Updated Contact", "contact_phone": "+8613800000002", "estimated_amount": "99000.15", "source": "referral",
	})
	requireStatus(t, updated, http.StatusOK)
	requireStatus(t, recordAction(t, f.eastRep, lead.ID, "sales_lead.mark_contacted", "m1-"+f.phase+"-contacted-bf01", nil), http.StatusOK)
	requireStatus(t, recordAction(t, f.eastRep, lead.ID, "sales_lead.mark_qualified", "m1-"+f.phase+"-qualified-bf01", nil), http.StatusOK)

	peerDenied := recordAction(t, f.eastPeer, lead.ID, "sales_lead.update_details", "m1-"+f.phase+"-peer-update-bf01", map[string]any{
		"contact_name": "Forbidden", "estimated_amount": "1.00", "source": "outbound",
	})
	requireDenied(t, peerDenied)
	terminal := getRecord(t, f.eastRep, "sales_lead", lead.ID)
	if fmt.Sprint(terminal.Data["status"]) != "qualified" || fmt.Sprint(terminal.Data["contact_name"]) != "Updated Contact" || fmt.Sprint(terminal.Data["estimated_amount"]) != "99000.15" {
		t.Fatalf("BF01 durable state was changed by denied write: %#v", terminal.Data)
	}
	audits := findRecords(listRecords(t, f.eastDirector, "lead_audit"), "lead_id", lead.ID)
	if len(audits) < 4 {
		t.Fatalf("expected create/update/two transition audits, got %d", len(audits))
	}
}

// TestBF02 traces CRM-R06..CRM-R08, CRM-R10 and CRM-R13.
// Preconditions: an owner-held qualified lead is below the exact 100000.00 threshold.
// Actions: invoke direct conversion twice with one idempotency key and attempt customer mutation.
// Terminal assertions: converted lead, exactly one linked customer, read-only customer, unchanged replay state.
func TestBF02DirectConversionIsAtomicReadOnlyAndIdempotent(t *testing.T) {
	f := newFixture(t)
	lead := progressQualified(t, f, f.eastRep, "BF02", "99999.99")
	key := "m1-" + f.phase + "-convert-bf02"
	requireStatus(t, recordAction(t, f.eastRep, lead.ID, "sales_lead.convert_direct", key, nil), http.StatusOK)
	requireStatus(t, recordAction(t, f.eastRep, lead.ID, "sales_lead.convert_direct", key, nil), http.StatusOK)
	terminal := getRecord(t, f.eastRep, "sales_lead", lead.ID)
	if fmt.Sprint(terminal.Data["status"]) != "converted" || customerCountForLead(t, f.eastDirector, lead.ID) != 1 {
		t.Fatalf("direct conversion terminal state/customer cardinality failed: %#v", terminal.Data)
	}
	customers := findRecords(listRecords(t, f.eastDirector, "customer"), "source_lead_id", lead.ID)
	mutation := f.eastDirector.request(http.MethodPatch, "/records/customer/items/"+url.PathEscape(customers[0].ID), map[string]any{"data": map[string]any{"company_name": "Forbidden"}}, "m1-customer-write-bf02")
	requireDenied(t, mutation)
	if customerCountForLead(t, f.eastDirector, lead.ID) != 1 || fmt.Sprint(getRecord(t, f.eastDirector, "customer", customers[0].ID).Data["company_name"]) == "Forbidden" {
		t.Fatalf("customer read-only/idempotency invariant failed")
	}
}

// TestBF03 traces CRM-R06..CRM-R09 and CRM-R13.
// Preconditions: a qualified lead is exactly at the large-lead threshold and a director task assignee exists.
// Actions: owner starts Workflow, sales approval is denied, director approves.
// Terminal assertions: one converted lead/customer transaction, completed approval process, owner notification.
func TestBF03LargeLeadDirectorApprovalConvertsAndNotifies(t *testing.T) {
	f := newFixture(t)
	lead := progressQualified(t, f, f.eastRep, "BF03", "100000.00")
	directTerminal := recordAction(t, f.eastDirector, lead.ID, "sales_lead.approve_conversion", "m1-direct-terminal-bf03", nil)
	requireDenied(t, directTerminal)
	runApproval(t, f, lead, true)
	terminal := getRecord(t, f.eastDirector, "sales_lead", lead.ID)
	if fmt.Sprint(terminal.Data["status"]) != "converted" || customerCountForLead(t, f.eastDirector, lead.ID) != 1 {
		t.Fatalf("approved conversion was not atomically durable: %#v", terminal.Data)
	}
	waitNotification(t, f.eastRep, "lead.conversion_approved", lead.ID)
}

// TestBF04 traces CRM-R06..CRM-R09 and CRM-R13 rejection semantics.
// Preconditions: a qualified lead exceeds the approval threshold.
// Actions: owner starts Workflow and director rejects with a reason.
// Terminal assertions: qualified status plus durable reason/notification, no customer, and denied direct terminal Action.
func TestBF04LargeLeadRejectionPersistsReasonWithoutCustomer(t *testing.T) {
	f := newFixture(t)
	lead := progressQualified(t, f, f.eastRep, "BF04", "250000.75")
	runApproval(t, f, lead, false)
	terminal := getRecord(t, f.eastDirector, "sales_lead", lead.ID)
	if fmt.Sprint(terminal.Data["status"]) != "qualified" || !strings.Contains(fmt.Sprint(terminal.Data["rejection_reason"]), "budget validation") {
