func progressQualified(t *testing.T, f fixture, client apiClient, suffix, amount string) record {
	t.Helper()
	lead := createLead(t, f, client, suffix, amount)
	requireStatus(t, recordAction(t, client, lead.ID, "sales_lead.mark_contacted", "m1-"+f.phase+"-contacted-"+strings.ToLower(suffix), nil), http.StatusOK)
	requireStatus(t, recordAction(t, client, lead.ID, "sales_lead.mark_qualified", "m1-"+f.phase+"-qualified-"+strings.ToLower(suffix), nil), http.StatusOK)
	lead = getRecord(t, client, "sales_lead", lead.ID)
	if fmt.Sprint(lead.Data["status"]) != "qualified" {
		t.Fatalf("lead %s did not reach qualified: %#v", lead.ID, lead.Data)
	}
	return lead
}

func customerCountForLead(t *testing.T, director apiClient, leadID string) int {
	t.Helper()
	return len(findRecords(listRecords(t, director, "customer"), "source_lead_id", leadID))
}

func inboxItems(t *testing.T, client apiClient) []map[string]any {
	t.Helper()
	response := client.request(http.MethodGet, "/notification/inbox?limit=200", nil, "")
	requireStatus(t, response, http.StatusOK)
	var page struct {
		Items []map[string]any `json:"items"`
	}
	response.decode(t, &page)
	return page.Items
}

func notificationCount(items []map[string]any, eventType, subjectID string) int {
	count := 0
	for _, item := range items {
		if fmt.Sprint(item["event_type"]) == eventType && (subjectID == "" || fmt.Sprint(item["subject_id"]) == subjectID) {
			count++
		}
	}
	return count
}

func waitNotification(t *testing.T, client apiClient, eventType, subjectID string) {
	t.Helper()
	deadline := time.Now().Add(8 * time.Second)
	for {
		if notificationCount(inboxItems(t, client), eventType, subjectID) > 0 {
			return
		t.Fatalf("published discovery omits weekday reminder Workflow")
	}
}

// TestBF07 traces CRM-R15 plus CRM-R01 monetary precision and CRM-R12 authorization.
// Preconditions: the director-visible dataset includes deterministic rows in every lifecycle state.
// Actions: execute the Object SQL funnel and independently aggregate the authorized record set.
// Terminal assertions: exact per-status counts/decimal sums and sales query denial.
func TestBF07DirectorFunnelMatchesAuthorizedRecordsAndDeniesSales(t *testing.T) {
	f := newFixture(t)
	_ = createLead(t, f, f.eastRep, "BF07-NEW", "1.11")
	contacted := createLead(t, f, f.eastRep, "BF07-CONTACTED", "2.22")
	requireStatus(t, recordAction(t, f.eastRep, contacted.ID, "sales_lead.mark_contacted", "m1-"+f.phase+"-bf07-contacted", nil), http.StatusOK)
	_ = progressQualified(t, f, f.eastRep, "BF07-QUALIFIED", "3.33")
	converted := progressQualified(t, f, f.eastRep, "BF07-CONVERTED", "4.44")
	requireStatus(t, recordAction(t, f.eastRep, converted.ID, "sales_lead.convert_direct", "m1-"+f.phase+"-bf07-converted", nil), http.StatusOK)
	lost := progressQualified(t, f, f.eastRep, "BF07-LOST", "5.55")
	requireStatus(t, recordAction(t, f.eastRep, lost.ID, "sales_lead.mark_lost", "m1-"+f.phase+"-bf07-lost", map[string]any{"reason": "not a fit"}), http.StatusOK)

	expectedCount := map[string]int{}
	expectedSum := map[string]*big.Rat{}
	for _, lead := range listRecords(t, f.eastDirector, "sales_lead") {
		status := fmt.Sprint(lead.Data["status"])
		expectedCount[status]++
		if expectedSum[status] == nil {
			expectedSum[status] = new(big.Rat)
		}
		expectedSum[status].Add(expectedSum[status], decimal(lead.Data["estimated_amount"]))
	}
	query := f.eastDirector.request(http.MethodPost, "/report/lead_funnel/query", map[string]any{"parameters": map[string]any{}, "page_size": 200}, "")
	requireStatus(t, query, http.StatusOK)
	var summary struct {
		Rows []struct {
			Dimensions map[string]string `json:"dimensions"`
			Measures   map[string]string `json:"measures"`
		} `json:"rows"`
	}
	query.decode(t, &summary)
	actualStatuses := map[string]bool{}
	for _, row := range summary.Rows {
		values := map[string]string{}
		for key, value := range row.Dimensions {
			values[key] = value
		}
		for key, value := range row.Measures {
			values[key] = value
		}
		status := values["status"]
		actualStatuses[status] = true
		if fmt.Sprint(expectedCount[status]) != values["lead_count"] || decimal(values["estimated_amount_total"]).Cmp(expectedSum[status]) != 0 {
			t.Fatalf("funnel mismatch for %s: row=%v count=%d sum=%s", status, values, expectedCount[status], expectedSum[status])
		}
	}
	for _, status := range sortedKeys(expectedCount) {
		if !actualStatuses[status] {
			t.Fatalf("funnel omitted status %s", status)
		}
	}
	requireDenied(t, f.eastRep.request(http.MethodPost, "/report/lead_funnel/query", map[string]any{"parameters": map[string]any{}}, ""))
}

// TestBF08 traces CRM-R16, CRM-R17 and CRM-R19.
// Preconditions: director and sales sessions exist and at least one lead is exportable.
// Actions: deny sales prepare, director prepares/polls/downloads CSV, inspect requester-owned audit, test another director.
// Terminal assertions: bounded completed job, CSV artifact, downloaded audit, requester-only job/audit visibility.
func TestBF08GovernedCSVExportIsAuditedRequesterOnlyAndDownloadable(t *testing.T) {
	f := newFixture(t)
	_ = createLead(t, f, f.eastRep, "BF08", "76543.21")
	scope := map[string]any{
		"parameters": map[string]any{}, "timezone": "Asia/Shanghai", "purpose": "M1 acceptance governed lead export",
		"field_projection": []string{"company_name", "contact_name", "contact_phone", "estimated_amount", "source", "status", "created_at", "updated_at"},
		"freshness":        map[string]any{"mode": "realtime"},
	}
	salesDenied := f.eastRep.request(http.MethodPost, "/report/lead_detail_export/exports/sales_lead/prepare", map[string]any{
		"audit_id": "m1-sales-denied-" + f.phase, "scope": scope,
	}, "m1-"+f.phase+"-sales-export-denied")
	requireDenied(t, salesDenied)
	auditID := "m1-export-audit-" + f.phase
	prepare := f.eastDirector.request(http.MethodPost, "/report/lead_detail_export/exports/sales_lead/prepare", map[string]any{
		"audit_id": auditID, "scope": scope,
	}, "m1-"+f.phase+"-director-export")
	requireStatus(t, prepare, http.StatusAccepted)
	var job struct {
		ID, Status   string
		RowsExported int `json:"rows_exported"`
	}
	prepare.decode(t, &job)
	if job.ID == "" {
		t.Fatalf("export prepare returned no job: %s", prepare.Body)
	}
	jobPath := "/data-exchange/jobs/" + url.PathEscape(job.ID) + "?provider=reports&operation=export"
	deadline := time.Now().Add(20 * time.Second)
	for job.Status != "completed" {
		polled := f.eastDirector.request(http.MethodGet, jobPath, nil, "")
		requireStatus(t, polled, http.StatusOK)
		polled.decode(t, &job)
		if job.Status == "failed" {
			t.Fatalf("governed export failed: %s", polled.Body)
		}
		if time.Now().After(deadline) {
			t.Fatalf("export did not complete, last status=%s", job.Status)
		}
		time.Sleep(150 * time.Millisecond)
	}
	if job.RowsExported > 10000 {
		t.Fatalf("export exceeded 10000-row control: %d", job.RowsExported)
	}
	requireDenied(t, f.northDirector.request(http.MethodGet, jobPath, nil, ""))
	download := f.eastDirector.request(http.MethodGet, "/data-exchange/jobs/"+url.PathEscape(job.ID)+"/download?provider=reports&operation=export", nil, "")
	requireStatus(t, download, http.StatusOK)
	if !strings.Contains(download.Header.Get("Content-Type"), "text/csv") || !strings.Contains(string(download.Body), "company_name") {
		t.Fatalf("download is not a lead CSV: content-type=%s body=%s", download.Header.Get("Content-Type"), download.Body)
	}
	audits := findRecords(listRecords(t, f.eastDirector, "lead_export_audit"), "job_id", job.ID)
	if len(audits) != 1 || fmt.Sprint(audits[0].Data["requester_id"]) != "m1-director-east" || fmt.Sprint(audits[0].Data["status"]) != "downloaded" {
		t.Fatalf("governed export audit mismatch: %#v", audits)
	}
	for _, audit := range listRecords(t, f.northDirector, "lead_export_audit") {
		if fmt.Sprint(audit.Data["job_id"]) == job.ID {
			t.Fatalf("another director can see requester-owned export audit")
		}
	}
}

	requireStatus(t, assignmentsResponse, http.StatusOK)
