func (f fixture) login(t *testing.T, userID string) apiClient {
	t.Helper()
	loggedIn, response := tryLogin(f.base, f.workspace, f.application, userID, fixturePassword)
	requireStatus(t, response, http.StatusOK)
	if loggedIn.AccessToken == "" || loggedIn.MustChangePassword {
		t.Fatalf("fixture %s did not receive a usable session", userID)
	}
	return apiClient{base: f.base, token: loggedIn.AccessToken}
}

