func runApproval(t *testing.T, f fixture, lead record, approve bool) {
	t.Helper()
	payload := map[string]any{"object_key": "sales_lead", "record_id": lead.ID, "id": lead.ID}
	for key, value := range lead.Data {
		payload[key] = value
	}
	run := f.eastRep.request(http.MethodPost, "/workflow/definitions/large_lead_conversion_approval/run", map[string]any{"payload": payload}, "m1-"+f.phase+"-workflow-"+lead.ID)
	requireStatus(t, run, http.StatusOK)
	var result struct {
		ProcessID string `json:"process_id"`
	}
	run.decode(t, &result)
	if result.ProcessID == "" {
		t.Fatalf("workflow run has no process_id: %s", run.Body)
	}
	var tasks []struct {
		ID        string `json:"id"`
		ProcessID string `json:"process_id"`
		Status    string `json:"status"`
	}
	deadline := time.Now().Add(8 * time.Second)
	var taskID string
	for taskID == "" {
		response := f.eastDirector.request(http.MethodGet, "/workflow/tasks?status=pending&limit=200", nil, "")
		requireStatus(t, response, http.StatusOK)
		response.decode(t, &tasks)
		for _, task := range tasks {
			if task.ProcessID == result.ProcessID {
				taskID = task.ID
			}
		}
		if taskID == "" && time.Now().After(deadline) {
			t.Fatalf("approval task for process %s did not materialize", result.ProcessID)
		}
		if taskID == "" {
			time.Sleep(100 * time.Millisecond)
		}
	}
	unauthorized := f.eastRep.request(http.MethodPost, "/workflow/tasks/"+url.PathEscape(taskID)+"/approve", map[string]any{"comment": "not a director"}, "m1-unauthorized-"+lead.ID)
	requireDenied(t, unauthorized)
	decision, comment := "approve", "approved by M1 acceptance director"
	if !approve {
		decision, comment = "reject", "M1 rejection: budget validation required"
	}
	decided := f.eastDirector.request(http.MethodPost, "/workflow/tasks/"+url.PathEscape(taskID)+"/"+decision, map[string]any{"comment": comment}, "m1-"+f.phase+"-decision-"+lead.ID)
	requireStatus(t, decided, http.StatusOK)
}

func decimal(value any) *big.Rat {
	result := new(big.Rat)
	if _, ok := result.SetString(fmt.Sprint(value)); !ok {
		panic(fmt.Sprintf("invalid decimal %v", value))
	}
	return result
}

func sortedKeys[V any](values map[string]V) []string {
	keys := make([]string, 0, len(values))
	for key := range values {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	return keys
